REV='032800e94bb0828c45d3f5195ac5cc17aa93bc4c'
EXPECTED_WEIGHTS={'shortpose_heldout.zip':'507c0a5decf79a4a48b982987e89c37b8c99e456f5c7f11cc3d49f34bd5741ec','shortpose_heldout_five_seeds.zip':'0bf2745ab2d5ddcf5f5fbb5d330e6c6cc800625cec301f4c7105d031bdb49d2d'}
def sha(b):return hashlib.sha256(b).hexdigest()
def verify(p):
 with zipfile.ZipFile(p) as z:
  a=json.loads(z.read('aggregate.json'));m=json.loads(z.read('sha256.json'));assert z.testzip() is None and set(m)==set(z.namelist())-{'sha256.json'}
  assert all(sha(z.read(k))==h for k,h in m.items()) and a['script_sha256']==SOURCES['third_score_cloud.py'][0] and a['protocol_sha256']==SOURCES['third_cohort_freeze.json'][0]
  assert a['coverage']['windows']==54 and len(a['weights_sha256'])==8 and set(a['summary_by_rotation'])=={'0','90','180','270','by_sequence','by_intersection'}
def run():
 root=Path('/kaggle/input');out=Path('/kaggle/working/dair_roadside_third_cohort.zip')
 if not root.is_dir() or not out.parent.is_dir():raise RuntimeError('Use a Kaggle CPU worker')
 if out.exists():verify(out);print('Verified existing result',out,sha(out.read_bytes()),flush=True);return
 with tempfile.TemporaryDirectory(prefix='dair_native_') as temp:
  temp=Path(temp);repo=temp/'repo';code=temp/'experiment';code.mkdir()
  for name,(expected,s) in SOURCES.items():
   payload=zlib.decompress(base64.b85decode(s));assert sha(payload)==expected;(code/name).write_bytes(payload)
  subprocess.run(['git','init','-q',str(repo)],check=True)
  subprocess.run(['git','-C',str(repo),'fetch','-q','--depth=1','https://github.com/pjyyyds/Unstructured-ShortPose-Pred.git',REV],check=True)
  subprocess.run(['git','-C',str(repo),'checkout','-q','--detach','FETCH_HEAD'],check=True)
  assert subprocess.check_output(['git','-C',str(repo),'rev-parse','HEAD'],text=True).strip()==REV
  sys.path.insert(0,str(repo))
  from scripts.run_heldout_cloud import MODEL_URL,MODEL_SHA,download_zip
  pose=next((p for p in sorted(root.rglob('*.onnx')) if p.stat().st_size==54330655 and sha(p.read_bytes())==MODEL_SHA),None)
  if not pose:
   modelzip=temp/'rtmpose.zip';download_zip(MODEL_URL,modelzip,50799818)
   with zipfile.ZipFile(modelzip) as z:
    candidates=[n for n in z.namelist() if Path(n).name=='end2end.onnx' and '__MACOSX' not in Path(n).parts]
    assert len(candidates)==1;blob=z.read(candidates[0]);assert sha(blob)==MODEL_SHA;pose=temp/'end2end.onnx';pose.write_bytes(blob)
  weights=next((p for name,digest in EXPECTED_WEIGHTS.items() for p in sorted(root.rglob(name)) if sha(p.read_bytes())==digest),None)
  if weights is None:weights=root # individual mounted states are accepted only when all eight original member hashes match
  if importlib.util.find_spec('onnxruntime') is None:subprocess.run([sys.executable,'-m','pip','-q','install','onnxruntime'],check=True)
  env={**os.environ,'PYTHONPATH':str(repo),'PYTHONDONTWRITEBYTECODE':'1','CUDA_VISIBLE_DEVICES':'','OMP_NUM_THREADS':'2','MKL_NUM_THREADS':'2','OPENBLAS_NUM_THREADS':'1'}
  spliturl='https://raw.githubusercontent.com/AIR-THU/DAIR-V2X/c885c54af0c34bc515fa9ca8b5e8fda76a15462c/data/split_datas/cooperative-split-data-spd.json'
  rawsplit=urllib.request.urlopen(spliturl,timeout=45).read();assert sha(rawsplit)=='0a59332221f3618639f34fb70678d03c5221ab80fd69f2cf41acffca0d8859fd';(code/'full_split.json').write_bytes(rawsplit)
  subprocess.run([sys.executable,'-u',str(code/'third_coverage.py'),'--stage-past'],cwd=code,env=env,check=True)
  command=[sys.executable,'-u',str(code/'third_score_cloud.py'),str(weights),str(pose),str(out)]
  subprocess.run(command+['--check-only'],cwd=code,env=env,check=True);subprocess.run(command,cwd=code,env=env,check=True);verify(out)
 print('Verified fixed external result',out,out.stat().st_size,sha(out.read_bytes()),flush=True)
if __name__=='__main__':run()
